def build_rag_prompt(
    user_message: str,
    conversation_history: str = "",
    retrieved_context: str = "",
) -> str:
    """
    Build the final prompt sent to the LLM.
    """

    sections = []

    if conversation_history.strip():
        sections.append(
            f"""
<conversation_history>
{conversation_history}
</conversation_history>
"""
        )

    if retrieved_context.strip():
        sections.append(
            f"""
<retrieved_context>
{retrieved_context}
</retrieved_context>
"""
        )

    sections.append(
        f"""
<user_question>
{user_message.strip()}
</user_question>
"""
    )

    return "\n".join(sections)

class DocumentProcessor:
    """
    Converts knowledge-base documents into meaningful chunks.

Chunking strategy:
        Markdown:
            Split by headings and keep sections together.

Python:
            Split primarily around classes/functions/methods.

Text:
            Split by paragraphs.

Large sections are split only when necessary.
    """

SUPPORTED_EXTENSIONS = {
        ".txt",
        ".md",
        ".py",
    }

def __init__(
        self,
        max_chunk_characters: int = 6000,
        overlap_characters: int = 500,
    ):
        self.max_chunk_characters = max(
            1000,
            max_chunk_characters,
        )

self.overlap_characters = max(
            0,
            min(
                overlap_characters,
                self.max_chunk_characters // 2,
            ),
        )

# ============================================================
    # PUBLIC API
    # ============================================================

def process(
        self,
        file_path: str,
    ) -> list[dict[str, Any]]:

path = Path(file_path)

if not path.exists():
            raise FileNotFoundError(
                f"Document not found: {file_path}"
            )

if path.suffix.lower() not in self.SUPPORTED_EXTENSIONS:
            return []

text = path.read_text(
            encoding="utf-8",
            errors="ignore",
        ).strip()

if not text:
            return []

extension = path.suffix.lower()

if extension == ".md":
            sections = self._split_markdown(text)

elif extension == ".py":
            sections = self._split_python(text)

else:
            sections = self._split_text(text)

chunks = []

for section in sections:

section = section.strip()

if not section:
                continue

if len(section) <= self.max_chunk_characters:
                chunks.append(section)
            else:
                chunks.extend(
                    self._split_large_section(section)
                )

return chunks

# ============================================================
    # MARKDOWN CHUNKING
    # ============================================================

def _split_markdown(
        self,
        text: str,
    ) -> list[str]:

lines = text.splitlines()

sections = []
        current = []

for line in lines:

# Markdown heading
            if re.match(
                r"^\s{0,3}#{1,6}\s+",
                line,
            ):

if current:
                    sections.append(
                        "\n".join(current).strip()
                    )
                    current = []

current.append(line)

if current:
            sections.append(
                "\n".join(current).strip()
            )

return [
            section
            for section in sections
            if section.strip()
        ]

# ============================================================
    # PYTHON CHUNKING
    # ============================================================

def _split_python(
        self,
        text: str,
    ) -> list[str]:

lines = text.splitlines()

sections = []
        current = []

for index, line in enumerate(lines):

stripped = line.lstrip()

is_top_level_definition = (
                (
                    stripped.startswith("class ")
                    or stripped.startswith("def ")
                    or stripped.startswith("async def ")
                )
                and len(line) - len(stripped) == 0
            )

if is_top_level_definition and current:

sections.append(
                    "\n".join(current).strip()
                )

current = []

current.append(line)

if current:
            sections.append(
                "\n".join(current).strip()
            )

return [
            section
            for section in sections
            if section.strip()
        ]

# ============================================================
    # PLAIN TEXT CHUNKING
    # ============================================================

def _split_text(
        self,
        text: str,
    ) -> list[str]:

paragraphs = re.split(
            r"\n\s*\n",
            text,
        )

return [
            paragraph.strip()
            for paragraph in paragraphs
            if paragraph.strip()
        ]

# ============================================================
    # LARGE SECTION SPLITTING
    # ============================================================

def _split_large_section(
        self,
        text: str,
    ) -> list[str]:

chunks = []

# First try paragraph boundaries.
        paragraphs = re.split(
            r"\n\s*\n",
            text,
        )

current = ""

for paragraph in paragraphs:

paragraph = paragraph.strip()

if not paragraph:
                continue

candidate = (
                f"{current}\n\n{paragraph}"
                if current
                else paragraph
            )

if (
                len(candidate)
                <= self.max_chunk_characters
            ):
                current = candidate
                continue

if current:
                chunks.append(current)

# A single paragraph is still too large.
            if len(paragraph) > self.max_chunk_characters:

sub_chunks = self._split_by_lines(
                    paragraph
                )

chunks.extend(sub_chunks)

current = ""

else:
                current = paragraph

if current:
            chunks.append(current)

return chunks

# ============================================================
    # LINE-BASED FALLBACK
    # ============================================================

def _split_by_lines(
        self,
        text: str,
