# ==========================================================
    # SAFE CONTENT
    # ==========================================================

@staticmethod
    def _clean_content(
        content: Any,
    ) -> str:
        """
        Safely convert candidate content to text.

Protects the reranker from malformed metadata or
        unexpected values.
        """

if content is None:
            return ""

if not isinstance(content, str):
            content = str(content)

return content.strip()

# ==========================================================
    # SAFE METADATA
    # ==========================================================

@staticmethod
    def _safe_metadata(
        metadata: Any,
    ) -> dict[str, Any]:
        """
        Ensure metadata always has a dictionary structure.
        """

if isinstance(
            metadata,
            dict,
        ):
            return dict(metadata)

return {}

# ==========================================================
    # SAFE SCORE
    # ==========================================================

@staticmethod
    def _safe_score(
        score: Any,
    ) -> float:
        """
        Safely convert similarity scores to float.

Invalid values become 0.0.
        """

try:
            value = float(score)
        except (
            TypeError,
            ValueError,
        ):
            return 0.0

if value != value:
            return 0.0

return max(
            0.0,
            min(value, 1.0),
        )

# ==========================================================
    # CLAMP
    # ==========================================================

@staticmethod
    def _clamp(
        value: float,
        minimum: float,
        maximum: float,
    ) -> float:
        """
        Keep a numeric value inside a safe range.
        """

return max(
            minimum,
            min(float(value), maximum),
        )

